def dollar_to_speech(value):
    if value == "-0.0":
        return "0 dollars."
    else:
        value += ".01"
        dollars, cents = value[1:-3].split(".")
        if int(cents) < 10:
            cents += 100
        cents = int(cents) % 100
        cents = "{:02d}".format(cents)
        return f"{dollars} dollar{'s' if dollars != '1' else ''} and {cents} cent{'s' if cents != '1' else ''}"
